                return info.getBlockSize();
            }

            @Override
            public Digest create() {
                return digest;
            }
        }, getCurrentTestName());
        String expected = thrown.getClass().getSimpleName();
        assertEquals("Mismatched fingerprint for " + thrown.getMessage(), expected, actual);
    }
}

