            NetworkInterface netint = nets.nextElement();
            if (!netint.isUp()) {
                // ignore non-running interfaces
                continue;
            }
            for (Enumeration<InetAddress> inetAddresses = netint.getInetAddresses(); (inetAddresses != null) && inetAddresses.hasMoreElements(); ) {
                InetAddress inetAddress = inetAddresses.nextElement();
                if (!(inetAddress instanceof Inet6Address)) {
                    continue;
                }
                try {
                    testConnectUsingIPv6Address(inetAddress.getHostAddress());
                } catch (IOException e) {
                    outputDebugMessage("Failed (%s) to connect to %s: %s", e.getClass().getSimpleName(), inetAddress, e.getMessage());
                }
            }
        }
    } finally {
        client.stop();
    }
}

