    Field[] fields = BuiltinCiphers.Constants.class.getFields();
    for (Field f : fields) {
        int mods = f.getModifiers();
        if (!Modifier.isStatic(mods)) {
            continue;
        }
        Class<?> type = f.getType();
        if (!String.class.isAssignableFrom(type)) {
