@Test
public void testParseOakleyGroupPrimeValues() throws Exception {
    List<String> lines;
    try (InputStream stream = DHGroupData.class.getResourceAsStream(name)) {
        assertNotNull("Missing prime value file for group=" + name, stream);
        lines = IoUtils.readAllLines(stream);
    }
    List<String> dataLines = new ArrayList<>();
    List<String> otherLines = new ArrayList<>();
    for (String raw : lines) {
        String l = GenericUtils.trimToEmpty(raw);
        l = l.replaceAll("\\s", "");
        if (GenericUtils.isEmpty(l) || l.startsWith("#")) {
            otherLines.add(raw);
        } else {
            dataLines.add(raw);
        }
    }
    Random rnd = new Random(System.nanoTime());
    for (int index = 1, numDataLines = dataLines.size(), numOtherLines = otherLines.size(); index <= 4; index++) {
        byte[] actual = DHGroupData.readOakleyGroupPrimeValue(lines.stream());
        assertArrayEquals(name + "[" + index + "]", expected, actual);
        lines.clear();
        // create an interleaving of the data lines and the other ones
        for (int dataIndex = 0, otherIndex = 0; (dataIndex < numDataLines) || (otherIndex < numOtherLines); ) {
            String l;
            if (dataIndex < numDataLines) {
                if (otherIndex < numOtherLines) {
                    if (rnd.nextBoolean()) {
                        l = dataLines.get(dataIndex);
                        dataIndex++;
                    } else {
                        l = otherLines.get(otherIndex);
                        otherIndex++;
                    }
                } else {
                    l = dataLines.get(dataIndex);
                    dataIndex++;
                }
            } else if (otherIndex < numOtherLines) {
                l = otherLines.get(otherIndex);
                otherIndex++;
            } else {
                throw new IllegalStateException("No more lines to interleave");
            }
            lines.add(l);
        }
    }
}

@Test
public void testEncodeDecodeExtensionMessage() throws IOException {
    List<Map.Entry<String, ?>> expected = Arrays.asList(new SimpleImmutableEntry<>(DelayCompression.NAME, new DelayedCompressionAlgorithms().withClient2Server(Arrays.asList(getClass().getSimpleName(), getCurrentTestName())).withServer2Client(Arrays.asList(getClass().getPackage().getName(), getCurrentTestName()))), new SimpleImmutableEntry<>(ServerSignatureAlgorithms.NAME, Arrays.asList(getClass().getPackage().getName(), getClass().getSimpleName(), getCurrentTestName())), new SimpleImmutableEntry<>(NoFlowControl.NAME, getCurrentTestName()), new SimpleImmutableEntry<>(Elevation.NAME, getCurrentTestName()));
    Buffer buffer = new ByteArrayBuffer();
    KexExtensions.putExtensions(expected, buffer);
    List<Map.Entry<String, ?>> actual = new ArrayList<>(expected.size());
    KexExtensionHandler handler = new KexExtensionHandler() {

        @Override
        public boolean handleKexExtensionRequest(Session session, int index, int count, String name, byte[] data) throws IOException {
            KexExtensionParser<?> parser = KexExtensions.getRegisteredExtensionParser(name);
            assertNotNull("No parser found for extension=" + name, parser);
            Object value = parser.parseExtension(data);
            assertNotNull("No value extracted for extension=" + name, value);
            actual.add(new SimpleImmutableEntry<>(name, value));
            return true;
        }
    };
    Session session = Mockito.mock(Session.class);
    handler.handleKexExtensionsMessage(session, buffer);
    assertEquals("Mismatched recovered extensions count", expected.size(), actual.size());
    for (int index = 0; index < actual.size(); index++) {
        Map.Entry<String, ?> expEntry = expected.get(index);
        String name = expEntry.getKey();
        Map.Entry<String, ?> actEntry = actual.get(index);
        assertEquals("Mismatched extension name at index=" + index, name, actEntry.getKey());
        Object expValue = expEntry.getValue();
        Object actValue = actEntry.getValue();
        if (expValue instanceof List<?>) {
            assertListEquals(name, (List<?>) expValue, (List<?>) actValue);
        } else {
            assertEquals("Mismatched values for extension=" + name, expValue, actValue);
        }
    }
}

