                    if (exchanges.get() > 0) {
                        outputDebugMessage("Stop sending after %d nanos and size=%d - exchanges=%s", timePassed, sentSize, exchanges);
                        break;
                    }
                    if ((timePassed < maxWaitNanos) && (nanoDuration < minWaitNanos)) {
                        Thread.sleep(minWaitValue);
                    }
                }
                teeOut.write("exit\n".getBytes(StandardCharsets.UTF_8));
                teeOut.flush();
                Collection<ClientChannelEvent> result = channel.waitFor(EnumSet.of(ClientChannelEvent.CLOSED), TimeUnit.SECONDS.toMillis(15L));
