@Test
public void testClientAddressOverride() throws Exception {
    final SshdSocketAddress expectedClientAddress = new SshdSocketAddress("7.3.6.5", 7365);
    String proxyMetadata = getCurrentTestName() + " " + expectedClientAddress.getHostName() + " " + expectedClientAddress.getPort();
    final byte[] metaDataBytes = (proxyMetadata + IoUtils.EOL).getBytes(StandardCharsets.UTF_8);
    sshd.setServerProxyAcceptor(new ServerProxyAcceptor() {

        private final AtomicInteger invocationCount = new AtomicInteger(0);

        @Override
        public boolean acceptServerProxyMetadata(ServerSession session, Buffer buffer) throws Exception {
            if (buffer.available() < metaDataBytes.length) {
                // wait for more data
                return false;
            }
            byte[] rawData = new byte[metaDataBytes.length];
            buffer.getRawBytes(rawData);
            outputDebugMessage("acceptServerProxyMetadata(%s) proxy data: %s", session, new String(rawData, StandardCharsets.UTF_8));
            assertArrayEquals("Mismatched meta data", metaDataBytes, rawData);
            int count = invocationCount.incrementAndGet();
            if (count == 1) {
                ((AbstractServerSession) session).setClientAddress(expectedClientAddress);
            } else {
                assertSame("Mismatched client address for invocation #" + count, expectedClientAddress, session.getClientAddress());
            }
            // proxy completed
            return true;
        }
    });
    final Semaphore sessionSignal = new Semaphore(0);
    sshd.addSessionListener(new SessionListener() {

        @Override
        public void sessionEvent(Session session, Event event) {
            verifyClientAddress(event.name(), session);
            if (Event.KeyEstablished.equals(event)) {
                sessionSignal.release();
            }
        }

        @Override
        public void sessionClosed(Session session) {
            verifyClientAddress("sessionClosed", session);
        }

        private void verifyClientAddress(String location, Session session) {
            assertObjectInstanceOf(location + ": not a server session", ServerSession.class, session);
            SocketAddress actualClientAddress = ((ServerSession) session).getClientAddress();
            assertSame(location + ": mismatched client address instance", expectedClientAddress, actualClientAddress);
        }
    });
    sshd.start();
    client.setClientProxyConnector(session -> {
        IoSession ioSession = session.getIoSession();
        ioSession.writePacket(new ByteArrayBuffer(metaDataBytes));
    });
    client.start();
    try (ClientSession session = client.connect(getCurrentTestName(), TEST_LOCALHOST, sshd.getPort()).verify(7L, TimeUnit.SECONDS).getSession()) {
        session.addPasswordIdentity(getCurrentTestName());
        session.auth().verify(11L, TimeUnit.SECONDS);
        assertTrue("Failed to receive session signal on time", sessionSignal.tryAcquire(13L, TimeUnit.SECONDS));
    } finally {
        client.stop();
    }
}

// see https://issues.apache.org/jira/browse/SSHD-456
@Test
public void testServerStillListensIfSessionListenerThrowsException() throws Exception {
    final Map<String, SocketAddress> eventsMap = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
    final Logger log = LoggerFactory.getLogger(getClass());
    SessionListener listener = new SessionListener() {

        @Override
        public void sessionCreated(Session session) {
            throwException("SessionCreated", session);
        }

        @Override
        public void sessionEvent(Session session, Event event) {
            throwException("SessionEvent", session);
        }

        @Override
        public void sessionClosed(Session session) {
            throwException("SessionClosed", session);
        }

        private void throwException(String phase, Session session) {
            IoSession ioSession = session.getIoSession();
            SocketAddress addr = ioSession.getRemoteAddress();
            synchronized (eventsMap) {
                if (eventsMap.put(phase, addr) != null) {
                    // already generated an event for this phase
                    return;
                }
            }
            RuntimeException e = new RuntimeException("Synthetic exception at phase=" + phase + ": " + addr);
            log.info(e.getMessage());
            throw e;
        }
    };
    sshd.addSessionListener(listener);
    int curCount = 0;
    try {
        for (int retryCount = 0; retryCount < Byte.SIZE; retryCount++) {
            synchronized (eventsMap) {
                curCount = eventsMap.size();
                if (curCount >= 3) {
                    return;
                }
            }
            try {
                try (ClientSession s = createTestClientSession()) {
                    log.info("Retry #" + retryCount + " successful");
                }
                synchronized (eventsMap) {
                    assertTrue("Unexpected premature success at retry # " + retryCount + ": " + eventsMap, eventsMap.size() >= 3);
                }
            } catch (IOException e) {
                // expected - ignored
                synchronized (eventsMap) {
                    int nextCount = eventsMap.size();
                    assertTrue("No session event generated at retry #" + retryCount, nextCount > curCount);
                }
            }
        }
    } finally {
        sshd.removeSessionListener(listener);
    }
    fail("No success to authenticate");
}

