@Test
public void testDecideEncryptedFileWithRetries() throws IOException, GeneralSecurityException {
    Assume.assumeTrue(BuiltinCiphers.aes256cbc.getTransformation() + " N/A", BuiltinCiphers.aes256cbc.isSupported());
    URL url = getClass().getResource(encryptedFile);
    Assume.assumeTrue("Skip non-existent encrypted file: " + encryptedFile, url != null);
    assertNotNull("Missing test resource: " + encryptedFile, url);
    int maxRetries = 3;
    SessionContext mockSession = Mockito.mock(SessionContext.class);
    for (ResourceDecodeResult result : ResourceDecodeResult.values()) {
        AtomicInteger retriesCount = new AtomicInteger(0);
        FilePasswordProvider provider = new FilePasswordProvider() {

            @Override
            public String getPassword(SessionContext session, NamedResource resourceKey, int retryIndex) throws IOException {
                assertSame("Mismatched session context", mockSession, session);
                switch(result) {
                    case IGNORE:
                    case TERMINATE:
                        assertEquals("Mismatched retries invocation count", 0, retryIndex);
                        assertEquals("Mismatched retries tracking count", retryIndex, retriesCount.get());
                        return "qwertyuiop123456!@#$%^";
                    case RETRY:
                        {
                            int count = retriesCount.incrementAndGet();
                            assertEquals("Mismatched retries count", retryIndex + 1, count);
                            if (count == maxRetries) {
                                return PASSWORD;
                            } else {
                                return "retry #" + count;
                            }
                        }
                    default:
                        throw new UnsupportedOperationException("Unknown decode result type: " + result);
                }
            }

            @Override
            public ResourceDecodeResult handleDecodeAttemptResult(SessionContext session, NamedResource resourceKey, int retryIndex, String password, Exception err) throws IOException, GeneralSecurityException {
                assertSame("Mismatched session context", mockSession, session);
                if (err == null) {
                    return null;
                }
                if (result == ResourceDecodeResult.RETRY) {
                    if (retriesCount.get() >= maxRetries) {
                        return ResourceDecodeResult.TERMINATE;
                    }
                }
                return result;
            }

            @Override
            public String toString() {
                return FilePasswordProvider.class.getSimpleName() + "[" + result + "]";
            }
        };
        try {
            Collection<KeyPair> keys = parser.loadKeyPairs(mockSession, url, provider);
            if (result == ResourceDecodeResult.IGNORE) {
                assertEquals("Unexpected loaded keys count from " + encryptedFile, 0, GenericUtils.size(keys));
                assertEquals("Mismatched " + result + " retries count", 0, retriesCount.get());
            } else {
                assertEquals("Mismatched loaded keys count from " + encryptedFile, 1, GenericUtils.size(keys));
                assertEquals("Mismatched " + result + " retries count", maxRetries, retriesCount.get());
                assertLoadedKeyPair(encryptedFile, GenericUtils.head(keys));
            }
        } catch (IOException | GeneralSecurityException | RuntimeException e) {
            if (result != ResourceDecodeResult.TERMINATE) {
                throw e;
            }
            assertEquals("Mismatched " + result + " retries count", 0, retriesCount.get());
        }
    }
}

@Test
public void testNormalizedScpRemotePaths() throws Exception {
    Path targetPath = detectTargetFolder();
    Path parentPath = targetPath.getParent();
    Path scpRoot = CommonTestSupportUtils.resolve(targetPath, ScpHelper.SCP_COMMAND_PREFIX, getClass().getSimpleName(), getCurrentTestName());
    CommonTestSupportUtils.deleteRecursive(scpRoot);
    Path localDir = assertHierarchyTargetFolderExists(scpRoot.resolve("local"));
    Path localFile = localDir.resolve("file.txt");
    byte[] data = CommonTestSupportUtils.writeFile(localFile, getClass().getName() + "#" + getCurrentTestName() + IoUtils.EOL);
    Path remoteDir = assertHierarchyTargetFolderExists(scpRoot.resolve("remote"));
    Path remoteFile = remoteDir.resolve(localFile.getFileName().toString());
    String localPath = localFile.toString();
    String remotePath = CommonTestSupportUtils.resolveRelativeRemotePath(parentPath, remoteFile);
    String[] remoteComps = GenericUtils.split(remotePath, '/');
    Factory<? extends Random> factory = client.getRandomFactory();
    Random rnd = factory.create();
    try (ClientSession session = client.connect(getCurrentTestName(), TEST_LOCALHOST, port).verify(CONNECT_TIMEOUT, TimeUnit.SECONDS).getSession()) {
        session.addPasswordIdentity(getCurrentTestName());
        session.auth().verify(AUTH_TIMEOUT, TimeUnit.SECONDS);
        ScpClient scp = createScpClient(session);
        StringBuilder sb = new StringBuilder(remotePath.length() + Long.SIZE);
        for (int i = 0; i < Math.max(Long.SIZE, remoteComps.length); i++) {
            if (sb.length() > 0) {
                // start again
                sb.setLength(0);
            }
            sb.append(remoteComps[0]);
            for (int j = 1; j < remoteComps.length; j++) {
                String name = remoteComps[j];
                slashify(sb, rnd);
                sb.append(name);
            }
            slashify(sb, rnd);
            String path = sb.toString();
            scp.upload(localPath, path);
            assertTrue("Remote file not ready for " + path, waitForFile(remoteFile, data.length, TimeUnit.SECONDS.toMillis(5L)));
            byte[] actual = Files.readAllBytes(remoteFile);
            assertArrayEquals("Mismatched uploaded data for " + path, data, actual);
            Files.delete(remoteFile);
            assertFalse("Remote file (" + remoteFile + ") not deleted for " + path, Files.exists(remoteFile));
        }
    }
}

