@Test
public void testScpExitStatusPropagation() throws Exception {
    final int testExitValue = 7365;
    class InternalScpCommand extends ScpCommand {

        InternalScpCommand(String command, CloseableExecutorService executorService, int sendSize, int receiveSize, ScpFileOpener opener, ScpTransferEventListener eventListener) {
            super(command, executorService, sendSize, receiveSize, opener, eventListener);
        }

        @Override
        protected void writeCommandResponseMessage(String command, int exitValue, String exitMessage) throws IOException {
            outputDebugMessage("writeCommandResponseMessage(%s) status=%d", command, exitValue);
            super.writeCommandResponseMessage(command, testExitValue, exitMessage);
        }

        @Override
        protected void onExit(int exitValue, String exitMessage) {
            outputDebugMessage("onExit(%s) status=%d", this, exitValue);
            super.onExit((exitValue == ScpHelper.OK) ? testExitValue : exitValue, exitMessage);
        }
    }
    ScpCommandFactory factory = (ScpCommandFactory) sshd.getCommandFactory();
    sshd.setCommandFactory(new ScpCommandFactory() {

        @Override
        public Command createCommand(String command) {
            ValidateUtils.checkTrue(command.startsWith(ScpHelper.SCP_COMMAND_PREFIX), "Bad SCP command: %s", command);
            return new InternalScpCommand(command, getExecutorService(), getSendBufferSize(), getReceiveBufferSize(), DefaultScpFileOpener.INSTANCE, ScpTransferEventListener.EMPTY);
        }
    });
    try (ClientSession session = client.connect(getCurrentTestName(), TEST_LOCALHOST, port).verify(CONNECT_TIMEOUT, TimeUnit.SECONDS).getSession()) {
