            try {
                ext.copyFile(srcPath, dstPath, false);
                fail("Unexpected success to overwrite existing destination: " + dstFile);
            } catch (IOException e) {
                assertTrue("Not an SftpException", e instanceof SftpException);
            }
        }
    }
}

